package Cx

import data.generic.ansible as ansLib
import data.generic.common as commonLib

contains_weak_jinja_hash(val) {
	weak_algs := {"md5", "sha1", "sha-1", "md4", "md2"}
	alg := weak_algs[_]
	contains(lower(val), sprintf("hash('%s')", [alg]))
}

contains_weak_jinja_hash(val) {
	weak_algs := {"md5", "sha1", "sha-1", "md4", "md2"}
	alg := weak_algs[_]
	contains(lower(val), sprintf("hash(\"%s\")", [alg]))
}

is_weak_prompt_encrypt(val) {
	weak := {"md5_crypt", "sha1_crypt", "des_crypt", "bsdi_crypt"}
	lower(val) == weak[_]
}

CxPolicy[result] {
	task := ansLib.tasks[id][_]
	[_, val] := walk(task)
	is_string(val)
	contains_weak_jinja_hash(val)

	result := {
		"documentId": id,
		"resourceType": "n/a",
		"resourceName": task.name,
		"searchKey": sprintf("name={{%s}}", [task.name]),
		"issueType": "IncorrectValue",
		"keyExpectedValue": "Template values should not use weak hash algorithms such as MD5 or SHA1",
		"keyActualValue": sprintf("Value uses a weak hash algorithm: '%s'", [val]),
	}
}

CxPolicy[result] {
	playbook := input.document[i].playbooks[_]
	vp := playbook.vars_prompt[_]
	commonLib.valid_key(vp, "encrypt")
	is_weak_prompt_encrypt(vp.encrypt)

	result := {
		"documentId": input.document[i].id,
		"resourceType": "n/a",
		"resourceName": "n/a",
		"searchKey": sprintf("vars_prompt.name={{%s}}.encrypt", [vp.name]),
		"issueType": "IncorrectValue",
		"keyExpectedValue": "vars_prompt 'encrypt' should use a strong algorithm such as 'sha256_crypt' or 'sha512_crypt'",
		"keyActualValue": sprintf("vars_prompt 'encrypt' is set to weak algorithm '%s'", [vp.encrypt]),
	}
}

